         acquire_exc_end() {
             require(pre.flag_rc == 0);

             remove pending_writer -= Some(());

             add writer += Some(());

             birds_eye let x = pre.storage->0;
             withdraw storage -= Some(x);

             assert Pred::inv(pre.k, x);
         }
